682	\begin{lemma}\label{lem:martingale_brownian_sq_sub_time}
683	  \uses{def:brownianNaturalFiltration}
684	  \lean{ProbabilityTheory.martingale_brownian_sq_sub_time}
685	The process \(B_t^2-t\) is a martingale with respect to the natural Brownian filtration.
686	\end{lemma}
687	
688	\begin{proof}
689	
690	It is adapted because \(B_t\) is \(\mathcal F^B_t\)-measurable and \(t\) is
691	deterministic.  It is integrable because \(B_t\) is Gaussian with finite second
692	moment.
693	
694	Fix \(s\le t\) and write \(\Delta_{s,t}=B_t-B_s\).  Then
695	\[
696	  B_t^2-t
697	  = B_s^2-s + 2B_s\Delta_{s,t}
698	    +\bigl(\Delta_{s,t}^2-(t-s)\bigr).
699	\]
700	The increment \(\Delta_{s,t}\) is independent of \(\mathcal F^B_s\), centered,
701	and has law \(N(0,t-s)\).  Therefore
702	\[
703	  \mathbb E[\Delta_{s,t}\mid\mathcal F^B_s]=0,
704	  \qquad
705	  \mathbb E[\Delta_{s,t}^2\mid\mathcal F^B_s]=t-s.
706	\]
707	Since \(B_s\) is \(\mathcal F^B_s\)-measurable, the mixed term has conditional
708	expectation
709	\[
710	  \mathbb E[B_s\Delta_{s,t}\mid\mathcal F^B_s]
711	  = B_s\,\mathbb E[\Delta_{s,t}\mid\mathcal F^B_s]=0.
712	\]
713	Taking conditional expectations in the displayed expansion gives
714	\[
715	  \mathbb E[B_t^2-t\mid\mathcal F^B_s]=B_s^2-s,
716	\]
717	which is the martingale property.
718	\end{proof}
